python3 -c "
import json
with open('/app/resources/treasury_bulletin_1980_05.json') as f:
    data = json.load(f)
# Print all keys at top level
def find_keys(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            print(f'{path}.{k}')
            if isinstance(v, (dict, list)):
                find_keys(v, f'{path}.{k}')
    elif isinstance(obj, list):
        for i, item in enumerate(obj[:5]):  # First 5 items
            find_keys(item, f'{path}[{i}]')

find_keys(data)
